/** The top AFK Gains Rate reference for a class — base merged with its profile. */
export function topAfkFlatForClass(classKey: string | null | undefined): FlatMap {
  const profile = classKey ? TOP_AFK_CLASS_PROFILE[classKey] : undefined;
  const override = profile ? TOP_AFK_PROFILE_OVERRIDES[profile] : undefined;
  return override ? { ...TOP_AFK_FLAT, ...override } : TOP_AFK_FLAT;
}
